// ─── UI Components ───────────────────────────────────────────────────────────

export { default as MenuBarTab } from "./components/ui/SidebarTab";

export interface Channel {
  id: number;
  name: string;
  desc: string;
  time: string;
}

export function ChannelItem({
  channel,
  onClick,
  onRename,
  onDelete,
}: {
  channel: Channel;
  onClick: (channel: Channel) => void;
  onRename: (channel: Channel) => void;
  onDelete: (channel: Channel) => void;
}) {
  const [hovered, setHovered] = useState(false);
  return (
    <div
      className={`channel-item ${hovered ? "hovered" : ""}`}
      onMouseEnter={() => setHovered(true)}
      onMouseLeave={() => setHovered(false)}
      onClick={() => onClick(channel)}
    >
      <div className="channel-icon">#</div>
      <div className="channel-info">
        <span className="channel-name">{channel.name}</span>
        <span className="channel-desc">{channel.desc}</span>
      </div>
      <div className="channel-right">
        {hovered && (
          <div className="channel-actions" onClick={(e) => e.stopPropagation()}>
            <RegularIconButton icon={<Pencil size={14} />} onClick={() => onRename(channel)} />
            <RegularIconButton icon={<Trash2 size={14} />} onClick={() => onDelete(channel)} />
          </div>
        )}
        <span className="channel-time">{channel.time}</span>
      </div>
    </div>
  );
}

export function Modal({
  title,
  open,
  onConfirm,
  onCancel,
  confirmLabel = "Confirm",
  cancelLabel = "Cancel",
  confirmDanger = false,
  children,
}: {
  title: string;
  open: boolean;
  onConfirm: () => void;
  onCancel: () => void;
  confirmLabel?: string;
  cancelLabel?: string;
  confirmDanger?: boolean;
  children?: React.ReactNode;
}) {
  const modalRef = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape") onCancel();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onCancel]);
  if (!open) return null;
  return (
    <div className="modal-backdrop" onClick={onCancel}>
      <div className="modal" ref={modalRef} onClick={(e) => e.stopPropagation()}>
        <h2 className="modal-title">{title}</h2>
        <div className="modal-body">{children}</div>
        <div className="modal-actions">
          <button className="modal-btn cancel" onClick={onCancel}>{cancelLabel}</button>
          <button className={`modal-btn confirm ${confirmDanger ? "danger" : ""}`} onClick={onConfirm}>{confirmLabel}</button>
        </div>
      </div>
    </div>
  );
}

export function RegularButton({
  children,
  onClick,
  variant = "default",
}: {
  children: React.ReactNode;
  onClick?: () => void;
  variant?: "default" | "primary";
}) {
  return (
    <button className={`regular-btn ${variant === "primary" ? "primary" : ""}`} onClick={onClick}>
      {children}
    </button>
  );
}

export function RegularIconButton({
  icon,
  onClick,
  variant = "default",
}: {
  icon: React.ReactNode;
  onClick?: () => void;
  variant?: "default" | "outlined";
}) {
  return (
    <button className={`regular-icon-btn ${variant === "outlined" ? "outlined" : ""}`} onClick={onClick}>
      {icon}
    </button>
  );
}

export function Title({
  children,
  rightBtn,
}: {
  children: React.ReactNode;
  rightBtn?: React.ReactNode;
}) {
  return (
    <div className="title-row">
      <span className="title-text">{children}</span>
      {rightBtn && <div className="title-right">{rightBtn}</div>}
    </div>
  );
}

// ─── Standalone Preview App ───────────────────────────────────────────────────

function PlaceholderPage({ title }: { title: string }) {
  return (
    <div className="flex h-full items-center justify-center bg-[var(--luci-surface-bg)] p-8">
      <div className="max-w-md rounded-[28px] border border-[var(--luci-border)] bg-[var(--luci-surface-tile)] p-8 text-center shadow-[var(--luci-floating-shadow)]">
        <p className="text-xs font-semibold uppercase tracking-[0.24em] text-[var(--luci-accent)]">Copied shell</p>
        <h1 className="mt-3 text-[28px] font-bold tracking-[-0.02em] leading-[1.15] text-[var(--text-0)]">{title}</h1>
        <p className="mt-3 text-sm leading-6 text-[var(--luci-text-tertiary)]">
          目前先按你的要求只放 sidebar 和 home。这里是占位页，设计可以继续往里加 Memories / Settings。
        </p>
      </div>
    </div>
  );
}

export default function App() {
  const [activeTab, setActiveTab] = useState<PrimaryNavigationItemId>("ask-luci");
  const [theme, setTheme] = useState<"light" | "dark">(() => {
    const saved = window.localStorage.getItem("luci.design.theme");
    return saved === "light" || saved === "dark" ? saved : "dark";
  });

  useEffect(() => {
    document.documentElement.dataset.theme = theme;
    document.documentElement.classList.toggle("dark", theme === "dark");
    document.documentElement.style.colorScheme = theme;
    window.localStorage.setItem("luci.design.theme", theme);
  }, [theme]);

  return (
    <main className="relative flex h-screen w-screen gap-3 overflow-hidden bg-[var(--luci-surface-bg)] p-3 md:gap-4 md:p-4">
      <Sidebar
        activeTab={activeTab}
        onChangeTab={setActiveTab}
        theme={theme}
        onToggleTheme={() => setTheme((value) => (value === "dark" ? "light" : "dark"))}
      />
      <div className="relative flex-1 overflow-hidden">
        <div className="absolute inset-0">
          <div
            className="h-full w-full overflow-hidden rounded-2xl md:rounded-[18px]"
            style={{ backgroundColor: "var(--page-surface-bg, var(--luci-surface-bg))" }}
          >
            {activeTab === "ask-luci" && <HomeMock />}
            {activeTab === "shadcn" && <ShadcnShowcase />}
            {activeTab === "css-vars" && <CssVariablesShowcase />}
            {activeTab === "memories" && <MemoriesMock />}
            {activeTab === "settings" && <PlaceholderPage title="Settings" />}
          </div>
        </div>
      </div>
    </main>
  );
}
